// Store original data for later use
const data = $input.item.json;
return {
  Influencer_Name: data.Influencer_Name || '',
  Recipient_Email: data.Recipient_Email || '',
  Description: data.Description || '',
  Website: data.Website || '',
  Instagram: data.Instagram || '',
  Subscriber_Count: data.Subscriber_Count || '',
  Source: data.Source || '',
  Channel_ID: data.Channel_ID || ''
};

// Parse Claude response and merge with original data
const originalData = $('Store Influencer Data').item.json;
const claudeResponse = $input.item.json;

let aiContent;
try {
  // Get the content from Claude response
  let content = '';
  if (claudeResponse.message && claudeResponse.message.content) {
    if (Array.isArray(claudeResponse.message.content)) {
      content = claudeResponse.message.content.map(item => item.text || '').join('');
    } else {
      content = claudeResponse.message.content;
    }
  } else if (claudeResponse.content) {
    if (Array.isArray(claudeResponse.content)) {
      content = claudeResponse.content.map(item => item.text || '').join('');
    } else {
      content = claudeResponse.content;
    }
  } else if (claudeResponse.text) {
    content = claudeResponse.text;
  }

  // Clean and parse the JSON
  const cleanedResponse = content.replace(/```json\n?|```\n?/g, '').trim();
  aiContent = JSON.parse(cleanedResponse);
} catch (e) {
  // Fallback defaults if parsing fails
  console.log('Parse error:', e.message);
  aiContent = {
    email_body: `I've been following your channel and really appreciate the depth of your content.\n\nWhat stands out is how you go beyond surface-level takes to give your audience real insight.\n\nI created something called Daily Sublime. It's a daily meditative art magazine, beautifully designed. Each morning features one artwork with a guided 10-minute analysis. It teaches visual literacy (composition, color theory, symbolism) and increases mindfulness. The same deep-thinking approach you bring to your content, applied to visual culture.\n\nI'm reaching out to about 10 creators whose audiences genuinely value depth and presence. Your community seems like exactly that kind of people.\n\nWant to try it for a week? Free access, no commitment. If it clicks, we can talk about a partnership. If not, I'd still love your honest feedback.`,
    subject_hook: 'your content',
    their_niche: 'content creation'
  };
}

// IMPORTANT: Explicitly pass through Recipient_Email and all original data
return {
  Influencer_Name: originalData.Influencer_Name || '',
  Recipient_Email: originalData.Recipient_Email || '',
  Description: originalData.Description || '',
  Website: originalData.Website || '',
  Instagram: originalData.Instagram || '',
  Subscriber_Count: originalData.Subscriber_Count || '',
  Source: originalData.Source || '',
  Channel_ID: originalData.Channel_ID || '',
  email_body: aiContent.email_body || '',
  subject_hook: aiContent.subject_hook || 'your content',
  their_niche: aiContent.their_niche || 'content creation'
};

// Generate summary of the workflow execution
const data = $input.item.json;
return {
  response: `✅ Email draft created for ${data.Influencer_Name || 'influencer'}

Email: ${data.email}
Subject: ${data.subject}

The draft has been saved to Gmail and status updated in Google Sheets.`
};
